// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin = address(this);
    address nonAdmin = address(0x1234);

    function setUp() public { c = new C(); }

    function testRegression_property() public {
        // Call setOwner with a non-admin address as argument
        // In reference, owner becomes nonAdmin; in bug, owner becomes admin
        vm.prank(admin);
        c.setOwner(nonAdmin);

        // Now attempt to call a function protected by onlyOwner as the nonAdmin
        // This will succeed on reference but revert on bug
        vm.prank(nonAdmin);
        bool ok;
        try c.setOwner(admin) { ok = true; } catch { ok = false; }

        // In reference, call succeeds (ok == true); in bug, it reverts (ok == false)
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        address admin = address(this);
        // initial owner is admin
        assertEq(c.owner(), admin);
        // admin calls setOwner with a different address
        c.setOwner(nonOwner);
        // In reference: owner becomes nonOwner, so admin can no longer call onlyOwner functions
        // In bug: owner becomes admin, so admin can still call onlyOwner functions
        // We attempt to call setOwner again as admin (which should now revert in reference but succeed in bug)
        // Since setOwner has onlyAdmin modifier, admin can call it; but in reference, after first call,
        // nonOwner is owner but admin is still admin, so admin can still call setOwner.
        // Actually, both should allow admin to call setOwner because onlyAdmin checks admin, not owner.
        // To observe divergence, we need to check a function that uses onlyOwner.
        // But C has no public onlyOwner function except setOwner which is onlyAdmin.
        // So we check owner directly: reference owner = nonOwner, bug owner = admin.
        assertTrue(c.owner() == nonOwner, "owner should be nonOwner");
    }
}
